export const canonicalAdoption35GeneratorSource = "import assert from \"node:assert/strict\";\nimport { createHash } from \"node:crypto\";\nimport { existsSync, lstatSync, readFileSync, readdirSync, writeFileSync } from \"node:fs\";\nimport { mkdir } from \"node:fs/promises\";\nimport { join, relative } from \"node:path\";\nimport { pathToFileURL } from \"node:url\";\nimport { gzipSync } from \"node:zlib\";\nimport { Database } from \"bun:sqlite\";\n\n// Exact adoption-v35 writer, not the distinct canonical notification-v35 cohort.\n// Only an archived public observation API runs. The PID is synthetic metadata;\n// no process is probed, launched, claimed, adopted, or otherwise controlled.\n// Later malformed-object tests must mutate copies and label those mutations.\nconst root = import.meta.dir;\nconst output = join(root, \"capture\");\nconst hash = (value: string | Uint8Array) => createHash(\"sha256\").update(value).digest(\"hex\");\nconst isRecord = (value: unknown): value is Record<string, unknown> =>\n  typeof value === \"object\" && value !== null && !Array.isArray(value)\n  && (Object.getPrototypeOf(value) === Object.prototype || Object.getPrototypeOf(value) === null);\nconst record = (value: unknown): Record<string, unknown> => {\n  if (!isRecord(value)) throw new Error(\"Expected a plain record.\");\n  return value;\n};\nconst string = (value: unknown): string => {\n  if (typeof value !== \"string\") throw new Error(\"Expected a string.\");\n  return value;\n};\nconst integer = (value: unknown): number => {\n  if (typeof value !== \"number\" || !Number.isSafeInteger(value) || value < 0) {\n    throw new Error(\"Expected a nonnegative safe integer.\");\n  }\n  return value;\n};\nconst exactKeys = (value: Record<string, unknown>, keys: readonly string[]) =>\n  assert.deepEqual(Object.keys(value).sort(), [...keys].sort());\n// Refuse whole-image and decoded private-root text in all three encodings.\n// Match either UTF-16 alignment; never normalize, scrub, or exempt a value.\nconst hostRoots = [\n  [\"\", \"Users\"], [\"\", \"home\"], [\"\", \"private\"], [\"\", \"tmp\"],\n  [\"\", \"var\", \"folders\"],\n].map((parts) => parts.join(\"/\"));\nhostRoots.push([\"\", \"Users\"].join(\"\\\\\"));\nconst assertPrivatePathFree = (value: string | Uint8Array) => {\n  const bytes = typeof value === \"string\" ? Buffer.from(value, \"utf8\") : Buffer.from(value);\n  for (const prefix of hostRoots) {\n    for (const suffix of [\"/\", \"\\\\\", \"\\u0000\", '\"', \"'\"]) {\n      const text = prefix + suffix;\n      const littleEndian = Buffer.from(text, \"utf16le\");\n      const bigEndian = Buffer.from(littleEndian);\n      bigEndian.swap16();\n      assert.equal(bytes.includes(Buffer.from(text, \"utf8\")), false, \"Private UTF-8 path refused.\");\n      assert.equal(bytes.includes(littleEndian), false, \"Private UTF-16LE path refused.\");\n      assert.equal(bytes.includes(bigEndian), false, \"Private UTF-16BE path refused.\");\n    }\n    if (typeof value === \"string\") {\n      assert.equal(value === prefix || value.includes(prefix + \"/\") || value.includes(prefix + \"\\\\\"), false);\n    }\n  }\n};\nconst assertDecodedPrivatePathFree = (value: unknown, depth = 0): void => {\n  assert.ok(depth <= 64);\n  if (typeof value === \"string\") { assertPrivatePathFree(value); return; }\n  if (value === null || typeof value === \"number\" || typeof value === \"boolean\") return;\n  if (Array.isArray(value)) {\n    assert.ok(value.length <= 4096);\n    for (const item of value) assertDecodedPrivatePathFree(item, depth + 1);\n    return;\n  }\n  for (const [key, item] of Object.entries(record(value))) {\n    assertPrivatePathFree(key);\n    assertDecodedPrivatePathFree(item, depth + 1);\n  }\n};\nconst definition = {\n  name: \"canonical35\",\n  cohort: \"adoption_v35\",\n  version: 35,\n  sourceCommit: \"42c4235e35daed1dec7eca4ff985bd9e8606b78a\",\n  sourceTree: \"a2445e9de4b8f29e9777ddb462730bc0cd7264d7\",\n  sourceParent: \"127c1e7dcf8ef1461b7d71ab4d077a93f85cc682\",\n  sourceFileCount: 255,\n  sourceManifestSha256: \"c15a0dcf85221a6666333ae84fc92a3e66b91d588fcd1df1bf98c90913a15dd5\",\n  sourceHashes: {\n    \"bun.lock\": \"2640e9d87062f81a175d4b022c377018e7c13bbe5065dcb904fac2b066fa703c\",\n    \"package.json\": \"ea27c368424d06054bf06fd424e049271ea8ec446e32fa0120136d2c2e04e73d\",\n    \"src/storage/paths.ts\": \"a5f898f825a3d277b710ed6635e889607f90cff33e9d41fbb395b27c5c540177\",\n    \"src/storage/state-store.ts\": \"7458beab48b541b4e2348dcc8af8a48cb33b3393f0140351f1bbe91aa584b165\",\n    \"src/storage/work-store.ts\": \"cf4f40ab840c702f26a7b9503fdc9f8c551a1e89741dc63a33bcdf9ab0fbc22e\",\n  },\n  dependencies: {\n    \"@hraness/oh\": \"0.2.7\",\n    \"@openai/codex\": \"0.153.2\",\n    convex: \"1.45.0\",\n    zod: \"4.4.3\",\n  },\n  installed: {\n    \"@hraness/oh\": { version: \"0.2.7\", sha256: \"ad5ea2f55afd7f2147558e8ee0ae73d6d38c96d9ae8ec97dc3aebf6d5dd5b05b\" },\n    \"@openai/codex\": { version: \"0.153.2\", sha256: \"4ecf4eae28684c5fcba8b9a63b946ce22b8cc2e451750f23c04e5088cf4c7a05\" },\n    convex: { version: \"1.45.0\", sha256: \"aa9f5baee26b69a88d6b61180e540cce1f52baa31094e7124c8c0393e4b3211e\" },\n    zod: { version: \"4.4.3\", sha256: \"c630bd10b52dcf71c112a2bf78dbf2734b9db58d62de663b8d86c2ec2c8cda2e\" },\n  },\n} as const;\nconst readBounded = (path: string) => {\n  const stat = lstatSync(path);\n  assert.equal(stat.isFile(), true);\n  assert.ok(stat.size <= 8 * 1024 * 1024);\n  return readFileSync(path);\n};\nconst verifySource = () => {\n  const sourceRoot = join(root, definition.name);\n  assert.equal(lstatSync(sourceRoot).isDirectory(), true);\n  for (const [path, expected] of Object.entries(definition.sourceHashes)) {\n    assert.equal(hash(readBounded(join(sourceRoot, path))), expected, path);\n  }\n  const files: { path: string; sha256: string }[] = [];\n  const visit = (directory: string, depth = 0) => {\n    assert.ok(depth <= 32);\n    for (const entry of readdirSync(directory, { withFileTypes: true })) {\n      assert.match(entry.name, /^[A-Za-z0-9_.-]+$/);\n      const path = join(directory, entry.name);\n      if (entry.isDirectory()) visit(path, depth + 1);\n      else if (entry.isFile()) files.push({ path: relative(sourceRoot, path), sha256: hash(readBounded(path)) });\n      else throw new Error(\"Unexpected source entry.\");\n      assert.ok(files.length <= definition.sourceFileCount);\n    }\n  };\n  visit(join(sourceRoot, \"src\"));\n  for (const path of [\"package.json\", \"bun.lock\"]) {\n    files.push({ path, sha256: hash(readBounded(join(sourceRoot, path))) });\n  }\n  files.sort((a, b) => a.path < b.path ? -1 : a.path > b.path ? 1 : 0);\n  assert.equal(files.length, definition.sourceFileCount);\n  assert.equal(hash(JSON.stringify(files)), definition.sourceManifestSha256);\n  const manifest = record(JSON.parse(readBounded(join(sourceRoot, \"package.json\")).toString(\"utf8\")) as unknown);\n  assert.equal(string(manifest.version), \"0.5.0\");\n  assert.deepEqual(record(manifest.dependencies), definition.dependencies);\n  for (const [name, expected] of Object.entries(definition.installed)) {\n    const bytes = readBounded(join(sourceRoot, \"node_modules\", name, \"package.json\"));\n    const installed = record(JSON.parse(bytes.toString(\"utf8\")) as unknown);\n    assert.equal(string(installed.name), name);\n    assert.equal(string(installed.version), expected.version);\n    assert.equal(hash(bytes), expected.sha256);\n  }\n  return files;\n};\nconst snapshot = (path: string) => {\n  const database = new Database(path, { create: false, strict: true });\n  database.exec(\"PRAGMA query_only=ON\");\n  try {\n    return database.transaction(() => {\n      const schema = database.query(\"SELECT type,name,tbl_name,sql FROM sqlite_schema WHERE name NOT LIKE 'sqlite_%' ORDER BY type,name LIMIT 2049\").all()\n        .map((value: unknown) => {\n          const row = record(value);\n          exactKeys(row, [\"type\", \"name\", \"tbl_name\", \"sql\"]);\n          assert.ok(row.sql === null || typeof row.sql === \"string\");\n          return { type: string(row.type), name: string(row.name), tbl_name: string(row.tbl_name), sql: row.sql };\n        });\n      assert.ok(schema.length <= 2048);\n      const tables = database.query(\"SELECT name FROM sqlite_schema WHERE type='table' ORDER BY name LIMIT 257\").all()\n        .map((value: unknown) => {\n          const row = record(value);\n          exactKeys(row, [\"name\"]);\n          return string(row.name);\n        });\n      assert.ok(tables.length <= 256);\n      const rows: Record<string, unknown[]> = {};\n      for (const name of tables) {\n        assert.match(name, /^[A-Za-z0-9_]+$/);\n        rows[name] = database.query(`SELECT * FROM \"${name}\" LIMIT 4097`).all()\n          .map((value: unknown) => record(value))\n          .sort((a, b) => JSON.stringify(a) < JSON.stringify(b) ? -1 : JSON.stringify(a) > JSON.stringify(b) ? 1 : 0);\n        assert.ok(rows[name].length <= 4096);\n      }\n      const rawVersion = record(database.query(\"PRAGMA user_version\").get());\n      exactKeys(rawVersion, [\"user_version\"]);\n      const version = integer(rawVersion.user_version);\n      const foreignKeys: unknown[] = database.query(\"PRAGMA foreign_key_check\").all();\n      assert.deepEqual(foreignKeys, []);\n      const changes = record(database.query(\"SELECT total_changes() AS count\").get());\n      exactKeys(changes, [\"count\"]);\n      assert.equal(integer(changes.count), 0);\n      const result = { version, schema, rows };\n      assert.ok(Buffer.byteLength(JSON.stringify(result)) <= 8 * 1024 * 1024);\n      assertDecodedPrivatePathFree(result);\n      return result;\n    }).deferred();\n  } finally { database.close(false); }\n};\nconst checkpoint = (path: string): void => {\n  const database = new Database(path, { create: false, strict: true });\n  try {\n    const row = record(database.query(\"PRAGMA wal_checkpoint(TRUNCATE)\").get());\n    exactKeys(row, [\"busy\", \"log\", \"checkpointed\"]);\n    assert.deepEqual(row, { busy: 0, log: 0, checkpointed: 0 });\n  } finally { database.close(false); }\n  if (existsSync(`${path}-wal`)) assert.equal(lstatSync(`${path}-wal`).size, 0);\n};\n\nassert.equal(Bun.version, \"1.3.14\");\nassert.equal(lstatSync(root).mode & 0o777, 0o700);\nassert.equal(existsSync(output), false, \"Never overwrite or resume a capture.\");\nconst sourceFiles = verifySource();\nconst generatorBytes = readBounded(import.meta.path);\nconst generatorSha256 = hash(generatorBytes);\nassertPrivatePathFree(generatorBytes);\nawait mkdir(output, { mode: 0o700 });\nconst sourceRoot = join(root, definition.name);\nconst { StateStore } = await import(pathToFileURL(join(sourceRoot, \"src/storage/state-store.ts\")).href);\nconst { initializeStatePaths, resolveStatePaths } = await import(pathToFileURL(join(sourceRoot, \"src/storage/paths.ts\")).href);\nconst paths = resolveStatePaths({ homeDirectory: join(output, \"state\"), platform: \"darwin\" });\nawait initializeStatePaths(paths);\nconst fixedTime = 1_000;\nconst request = {\n  provider: \"claude\",\n  providerThreadId: \"historical-v35-candidate\",\n  title: \"Historical v35 candidate\",\n  state: \"terminal\",\n  providerUpdatedAt: 10,\n  liveness: \"not_live\",\n  sourceProcessIdentity: {\n    pid: 46_001,\n    pidDomain: \"darwin\",\n    procStart: \"historical-v35-process\",\n  },\n} as const;\nconst store = new StateStore(paths, { now: () => fixedTime });\nlet candidate: unknown;\ntry {\n  candidate = store.upsertSessionAdoptionCandidate(request);\n  assert.deepEqual(candidate, {\n    provider: request.provider, providerThreadId: request.providerThreadId,\n    projectId: null, title: request.title, providerState: request.state,\n    activeTurnId: null, providerUpdatedAt: request.providerUpdatedAt,\n    liveness: request.liveness, sourceProcessIdentity: request.sourceProcessIdentity,\n    status: \"pending\", revision: 1, firstDiscoveredAt: fixedTime,\n    lastObservedAt: fixedTime, lastChangedAt: fixedTime, lastAttemptAt: null,\n  });\n  assert.deepEqual(store.listSessionAdoptionCandidates({ provider: \"claude\", limit: 2 }), [candidate]);\n} finally { store.close(); }\ncheckpoint(paths.database);\nconst before = snapshot(paths.database);\nassert.equal(before.version, 35);\nassert.equal(before.rows.session_adoption_candidates?.length, 1);\nfor (const name of [\"profiles\", \"sessions\", \"session_claude_process_launch_intents\", \"session_claude_process_authorities\", \"session_personal_runtime_bindings\", \"usage_snapshots\", \"usage_revision_authority\"]) {\n  assert.deepEqual(before.rows[name], [], `Unexpected populated ${name}.`);\n}\nconst rawCandidate = record(before.rows.session_adoption_candidates[0]);\nassert.match(string(rawCandidate.candidate_fingerprint), /^[a-f0-9]{64}$/);\nassert.equal(rawCandidate.source_pid, request.sourceProcessIdentity.pid);\nassert.equal(rawCandidate.source_proc_start, request.sourceProcessIdentity.procStart);\nassert.equal(rawCandidate.last_live_observed_at, undefined);\nassert.equal(rawCandidate.provider_project_root, undefined);\nconst ledger = (before.rows.migrations ?? []).map((value: unknown) => {\n  const row = record(value);\n  exactKeys(row, [\"version\", \"applied_at\"]);\n  return { version: integer(row.version), applied_at: integer(row.applied_at) };\n}).sort((a, b) => a.version - b.version);\nassert.deepEqual(ledger.map((row) => row.version), Array.from({ length: 35 }, (_, index) => index + 1));\nfor (const readonly of [false, true]) {\n  const bytesBefore = hash(readBounded(paths.database));\n  const reopened = new StateStore(paths, { now: () => fixedTime, readonly });\n  try {\n    assert.deepEqual(reopened.listSessionAdoptionCandidates({ provider: \"claude\", limit: 2 }), [candidate]);\n  } finally { reopened.close(); }\n  checkpoint(paths.database);\n  assert.deepEqual(snapshot(paths.database), before, \"Archived reopen changed source rows or schema.\");\n  if (readonly) assert.equal(hash(readBounded(paths.database)), bytesBefore, \"Readonly reopen changed image bytes.\");\n}\nconst databaseBytes = readBounded(paths.database);\nassert.ok(databaseBytes.length <= 4 * 1024 * 1024);\nassertPrivatePathFree(databaseBytes);\nconst compressed = gzipSync(databaseBytes, { level: 9 });\nconst metadata = {\n  ...definition, generatorSha256, fixedTime, request, candidate, rawCandidate, ledger,\n  databaseBytes: databaseBytes.length, databaseSha256: hash(databaseBytes),\n  gzipBytes: compressed.length, gzipSha256: hash(compressed),\n  snapshotSha256: hash(JSON.stringify(before)), schemaSha256: hash(JSON.stringify(before.schema)),\n  rowCounts: Object.fromEntries(Object.entries(before.rows).map(([name, rows]) => [name, rows.length])),\n  archivedRowsAndSchemaReopensUnchanged: true, archivedReadonlyImageUnchanged: true,\n  usageObservations: 0, unusedUsageReservations: 0,\n  proofScope: \"exact archived adoption-v35 public storage observation with synthetic process metadata; no native process, provider execution, launch, claim, or adoption proof\",\n};\nconst metadataBytes = Buffer.from(JSON.stringify(metadata, null, 2) + \"\\n\");\nconst manifestBytes = Buffer.from(JSON.stringify(sourceFiles, null, 2) + \"\\n\");\nassert.ok(metadataBytes.length <= 8 * 1024 * 1024);\nassert.ok(manifestBytes.length <= 1024 * 1024);\nassert.ok(compressed.length <= 4 * 1024 * 1024);\nassertPrivatePathFree(metadataBytes);\nassertPrivatePathFree(manifestBytes);\nassertDecodedPrivatePathFree(metadata);\nassertDecodedPrivatePathFree(sourceFiles);\nassert.equal(hash(readBounded(import.meta.path)), generatorSha256);\nassert.deepEqual(verifySource(), sourceFiles);\nwriteFileSync(join(output, \"state.sqlite.gz\"), compressed, { mode: 0o600, flag: \"wx\" });\nwriteFileSync(join(output, \"fixture.json\"), metadataBytes, { mode: 0o600, flag: \"wx\" });\nwriteFileSync(join(output, \"source-manifest.json\"), manifestBytes, { mode: 0o600, flag: \"wx\" });\nwriteFileSync(join(output, \"generator.original.ts.txt\"), generatorBytes, { mode: 0o600, flag: \"wx\" });\nconsole.log(JSON.stringify({ generatorSha256, sourceCommit: definition.sourceCommit,\n  databaseSha256: hash(databaseBytes), version: 35, archivedRowsAndSchemaReopensUnchanged: true,\n  archivedReadonlyImageUnchanged: true, providerEffects: 0 }));\n";

const compressed = {
  "base64": "",
  "gzipSha256": "e73d89e1434af875d3d581174881b0e70830d71024231a6d603baf8652c47609"
} as const;

export function canonicalAdoption35DatabaseBytes(): Buffer {
  const digest = (value: Uint8Array) => createHash("sha256").update(value).digest("hex");
  if (digest(Buffer.from(canonicalAdoption35GeneratorSource)) !== canonicalAdoption35Fixture.generatorSha256) throw new Error("HISTORICAL_RECIPE_MISMATCH");
  const packed = Buffer.from(compressed.base64, "base64");
  if (digest(packed) !== compressed.gzipSha256) throw new Error("HISTORICAL_GZIP_MISMATCH");
  const bytes = gunzipSync(packed, { maxOutputLength: 8 * 1024 * 1024 });
  if (bytes.length !== canonicalAdoption35Fixture.databaseBytes || digest(bytes) !== canonicalAdoption35Fixture.databaseSha256) throw new Error("HISTORICAL_IMAGE_MISMATCH");
  return bytes;
}
